import{_ as s,o as e,c as a,a6 as t}from"./chunks/framework.ZMCvXf1_.js";const k=JSON.parse('{"title":"Installing ignatius","description":"Install the ignatius binary and the ignatius-modeling skill, then serve, validate, and export your first model.","frontmatter":{"title":"Installing ignatius","description":"Install the ignatius binary and the ignatius-modeling skill, then serve, validate, and export your first model."},"headers":[],"relativePath":"modeling/installation.md","filePath":"modeling/installation.md"}'),n={name:"modeling/installation.md"};function l(h,i,d,o,r,p){return e(),a("div",null,[...i[0]||(i[0]=[t(`<h1 id="installing-ignatius" tabindex="-1">Installing ignatius <a class="header-anchor" href="#installing-ignatius" aria-label="Permalink to “Installing ignatius”">​</a></h1><p>ignatius is a single self-contained binary with no runtime dependency. It runs on machines without Bun or Node installed.</p><h2 id="install-script" tabindex="-1">Install script <a class="header-anchor" href="#install-script" aria-label="Permalink to “Install script”">​</a></h2><p>The script detects your operating system and architecture, downloads the matching binary from the <a href="https://github.com/noormdev/ignatius/releases/latest" target="_blank" rel="noreferrer">latest release</a>, verifies its checksum, and puts it on your <code>$PATH</code>.</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://raw.githubusercontent.com/noormdev/ignatius/main/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sh</span></span></code></pre></div><p>It installs to <code>/usr/local/bin</code> when that directory is writable and <code>$HOME/.local/bin</code> otherwise. Two environment variables override the defaults:</p><ul><li><code>IGNATIUS_INSTALL_DIR=/some/dir</code> installs somewhere else.</li><li><code>IGNATIUS_VERSION=v0.2.0</code> pins a release tag instead of taking the latest.</li></ul><p>Verify with <code>ignatius --help</code>.</p><h2 id="download-a-release" tabindex="-1">Download a release <a class="header-anchor" href="#download-a-release" aria-label="Permalink to “Download a release”">​</a></h2><p>To install by hand, or on Windows, take the binary for your platform from the <a href="https://github.com/noormdev/ignatius/releases/latest" target="_blank" rel="noreferrer">latest release</a>.</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># macOS arm64</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -L</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ignatius</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/noormdev/ignatius/releases/latest/download/ignatius-darwin-arm64</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +x</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ignatius</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ignatius</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/local/bin/</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Linux x64</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -L</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ignatius</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/noormdev/ignatius/releases/latest/download/ignatius-linux-x64</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +x</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ignatius</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ignatius</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/local/bin/</span></span></code></pre></div><p>Windows users take <code>ignatius-windows-x64.exe</code> from the same page. Each release includes <code>checksums.txt</code> for verifying a manual download with <code>shasum -a 256 -c</code>.</p><h2 id="from-source" tabindex="-1">From source <a class="header-anchor" href="#from-source" aria-label="Permalink to “From source”">​</a></h2><p>ignatius builds with <a href="https://bun.com" target="_blank" rel="noreferrer">Bun</a>.</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/noormdev/ignatius.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ignatius</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build:cli</span></span></code></pre></div><p>That produces <code>./dist/ignatius</code>.</p><h2 id="staying-current" tabindex="-1">Staying current <a class="header-anchor" href="#staying-current" aria-label="Permalink to “Staying current”">​</a></h2><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ignatius</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> version</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # print the installed version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ignatius</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">           # check for a newer release, then prompt</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ignatius</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --check</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # report only, never install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ignatius</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --yes</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # install without prompting, for scripts</span></span></code></pre></div><p><code>update</code> downloads the binary for your platform, verifies its checksum against the release <code>checksums.txt</code>, and replaces the running executable in place. That needs write access to the installed binary, so a binary in <code>/usr/local/bin</code> wants <code>sudo ignatius update --yes</code>. Outside a terminal it reports the available version and exits without installing unless you pass <code>--yes</code>. Windows binaries cannot replace themselves while running, so on Windows the command points you at the release download instead.</p><h2 id="the-modeling-skill" tabindex="-1">The modeling skill <a class="header-anchor" href="#the-modeling-skill" aria-label="Permalink to “The modeling skill”">​</a></h2><p>To author models from Claude Code, install the <code>ignatius-modeling</code> skill with the <a href="https://www.npmjs.com/package/skills" target="_blank" rel="noreferrer"><code>skills</code></a> CLI.</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/noormdev/ignatius</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --skill</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ignatius-modeling</span></span></code></pre></div><p>That adds the skill to the current project&#39;s <code>.claude/skills/</code>. Add <code>-g</code> to install it globally for every project on the machine. Reload skills in Claude Code and <code>/ignatius-modeling</code> becomes available. See <a href="/modeling/modeling-skill.html">The modeling skill</a> for what each mode does.</p><h2 id="serve-a-model" tabindex="-1">Serve a model <a class="header-anchor" href="#serve-a-model" aria-label="Permalink to “Serve a model”">​</a></h2><p>Point ignatius at a folder that contains an <code>ignatius.yml</code> file.</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ignatius</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> path/to/your/models</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3000</span></span></code></pre></div><p>Editing any <code>.md</code> or <code>.yaml</code> file under that folder pushes an update to the open browser tab over server-sent events, so the diagram reloads without a refresh.</p><p>The path argument is optional. With no path, ignatius searches up and down from the current directory for a model root. When it finds more than one it prompts you with a list in a terminal, or takes <code>--model &lt;key&gt;</code> to skip the prompt. In a non-interactive shell an ambiguous run exits with an error and prints the available keys rather than hanging. The search skips <code>node_modules</code>, <code>.git</code>, <code>dist</code>, <code>tmp</code>, <code>trash</code>, <code>.worktrees</code>, <code>.claude</code>, and any path segment starting with <code>_</code>.</p><p>The default port is 3000. When that port is taken, ignatius counts up to the next free one and asks which to use, with the free port as the default. Run non-interactively it advances automatically and prints the port it settled on. Pass <code>-o</code> to open the app in your browser once the server binds, on whichever port it ended up with.</p><p>The app has three views, switched without a page reload and reflected in the URL hash: Graph (<code>#view=graph</code>), Dictionary (<code>#view=dict</code>), and Flows (<code>#view=flow</code>). Back, forward, and deep links all work.</p><h2 id="validate-a-model" tabindex="-1">Validate a model <a class="header-anchor" href="#validate-a-model" aria-label="Permalink to “Validate a model”">​</a></h2><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ignatius</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> validate</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [path] [--model </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">key</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><p><code>validate</code> checks the model and reports findings without writing anything. It prints each finding to stderr and a one-line summary to stdout, then exits <code>1</code> when the model has errors and <code>0</code> otherwise. Warnings alone do not fail the command. When the model has a <code>flows/</code> directory the flow rules run too.</p><p>That exit-code contract makes it usable as a CI gate. Findings come in two classes: a warning still renders the entity with a badge, while an error omits the broken reference (one edge, one cluster, one unparseable file) and names the omission in a banner. A typo in one of three foreign keys strips that edge and keeps the entity. The <a href="https://github.com/noormdev/ignatius/blob/main/docs/guides/validation.md" target="_blank" rel="noreferrer">full rule catalog</a> lists every rule and its class.</p><h2 id="export-a-model" tabindex="-1">Export a model <a class="header-anchor" href="#export-a-model" aria-label="Permalink to “Export a model”">​</a></h2><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ignatius</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [path] -o model.html [--theme light</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">dark] [--model </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">key</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><p><code>export</code> writes all three views into one HTML file with no external dependencies. View switching, dictionary search, the entity dialog, the theme toggle, and node-position persistence all work offline from <code>file://</code>. <code>-o</code> is required.</p><p>This is the artifact you send to someone who will not install anything. Commit it next to the model, attach it to a ticket, or mail it to the stakeholder whose sign-off you need.</p><h2 id="keyboard-shortcuts" tabindex="-1">Keyboard shortcuts <a class="header-anchor" href="#keyboard-shortcuts" aria-label="Permalink to “Keyboard shortcuts”">​</a></h2><p>Single-key shortcuts work while no text field is focused and no modifier is held.</p><table tabindex="0"><thead><tr><th>Key</th><th>Action</th></tr></thead><tbody><tr><td><code>g</code></td><td>Switch to the Data Graph</td></tr><tr><td><code>d</code></td><td>Switch to the Dictionary</td></tr><tr><td><code>f</code></td><td>Switch to the Data Flows</td></tr><tr><td><code>l</code></td><td>Toggle graph layout, organic or hierarchical (Graph view)</td></tr><tr><td><code>b</code></td><td>Toggle dictionary lens, read or browse (Dictionary view)</td></tr><tr><td><code>/</code></td><td>Focus the search bar</td></tr><tr><td><code>?</code></td><td>Open the help overlay for the current view</td></tr><tr><td><code>↑</code> <code>↓</code> <code>←</code> <code>→</code></td><td>Pan the canvas (Graph and Flows); hold <code>Shift</code> for a longer step</td></tr></tbody></table><p>Zoom and search also answer to modifier chords. Those work even while a text field is focused, because the chords are not typed characters, and zoom acts on the diagram canvas rather than the browser page.</p><table tabindex="0"><thead><tr><th>Input</th><th>Action</th></tr></thead><tbody><tr><td><code>Cmd</code>/<code>Ctrl</code> + <code>=</code></td><td>Zoom in</td></tr><tr><td><code>Cmd</code>/<code>Ctrl</code> + <code>-</code></td><td>Zoom out</td></tr><tr><td><code>Cmd</code>/<code>Ctrl</code> + <code>0</code></td><td>Fit the diagram to the screen</td></tr><tr><td><code>Cmd</code>/<code>Ctrl</code> + <code>k</code></td><td>Focus the search bar</td></tr><tr><td>Trackpad pinch</td><td>Zoom toward the pointer</td></tr></tbody></table><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to “Next steps”">​</a></h2><ul><li><a href="/modeling/entities.html">Entities and key inheritance</a> covers the folder format and the entity file.</li><li><a href="/modeling/data-flows.html">Data flows</a> covers processes, externals, and stores.</li><li><a href="/modeling/modeling-skill.html">The modeling skill</a> covers authoring from Claude Code.</li></ul>`,45)])])}const g=s(n,[["render",l]]);export{k as __pageData,g as default};
